import numpy as np
D3={'TL':['.##.','####','#.##','.##.'],'TR':['.##.','####','#..#','....'],'ML':['..##','...#','.###','.##.'],'MR':['.##.','...#','.###','.##.'],'BL':['..##','#...','###.','.##.'],'BR':['....','##.#','##.#','.##.']}
def variants(a):
 x=np.array([[c=='#' for c in s] for s in a]);return [tuple(''.join('#' if v else '.' for v in row) for row in np.rot90(x,k)) for k in range(4)]+[tuple(''.join('#' if v else '.' for v in row) for row in np.rot90(np.fliplr(x),k)) for k in range(4)]
for name,arr in D3.items():
 print(name, sum(s.count('#') for s in arr), {n for n,b in D3.items() if n!=name and tuple(b) in variants(arr)})

